SELECT [PersonID],[FullName],[PreferredName],[SearchName],[IsPermittedToLogon],[LogonName],[IsExternalLogonProvider],[IsSystemUser],[IsEmployee],[IsSalesperson],[UserPreferences],[PhoneNumber],[FaxNumber],[EmailAddress],[CustomFields],[OtherLanguages],[LastEditedBy],CONVERT(nvarchar(33),[ValidFrom],126) AS [ValidFrom],CONVERT(nvarchar(33),[ValidTo],126) AS [ValidTo] FROM [Application].[People] ORDER BY [PersonID]